  void* ptr = RH3DM_R(ON_NurbsCurve_CreateControlPointCurve(count, RH3DM_Ptr((ptArray).data()), degree));
  return RH3DM_As<BND_NurbsCurve>(RH3DM_Wrap_GeometryBase(RH3DM_IP(ptr)));
